CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS public.activity_log (action text NOT NULL, created_at timestamptz, entity_id uuid, entity_name text, entity_type text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), metadata jsonb, org_id uuid, project_id uuid, user_id uuid);
CREATE TABLE IF NOT EXISTS public.ai_estimates (breakdown jsonb, city text, created_at timestamptz NOT NULL DEFAULT now(), estimated_total numeric, floors integer, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), input jsonb, org_id uuid, profile_id uuid, project_id uuid, project_type text, result jsonb, spec_level text, total_sqft numeric, user_id uuid);
CREATE TABLE IF NOT EXISTS public.bids (amount numeric NOT NULL, boq_url text, contractor_id uuid NOT NULL, created_at timestamptz, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), methodology text, razorpay_payment_id text, rejection_note text, status text, tender_id uuid NOT NULL, timeline_weeks integer);
CREATE TABLE IF NOT EXISTS public.cad_models (created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, document_id uuid, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, org_id uuid NOT NULL, project_id uuid, status text NOT NULL DEFAULT 'active', updated_at timestamptz NOT NULL DEFAULT now(), urn text NOT NULL);
CREATE TABLE IF NOT EXISTS public.client_interactions (client_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), interaction_date date, org_id uuid NOT NULL, summary text NOT NULL, type text NOT NULL);
CREATE TABLE IF NOT EXISTS public.client_portal_settings (project_id uuid PRIMARY KEY, show_approvals boolean, show_documents boolean, show_drawings boolean, show_overview boolean, show_payments boolean, show_questions boolean, show_site boolean, updated_at timestamptz, welcome_note text);
CREATE TABLE IF NOT EXISTS public.clients (city text, company text, created_at timestamptz NOT NULL DEFAULT now(), email text, full_name text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), last_contact text, name text NOT NULL, notes text, org_id uuid NOT NULL, phone text, pipeline_stage text, state text, total_value numeric);
CREATE TABLE IF NOT EXISTS public.consultant_payments (amount numeric NOT NULL DEFAULT 0, consultant_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, discipline text, due_date date, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), milestone_phase text, org_id uuid, paid_date date, project_id uuid NOT NULL, status text NOT NULL DEFAULT 'active', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.contractor_reviews (contractor_id uuid NOT NULL, created_at timestamptz, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid, rating numeric NOT NULL, review_text text, reviewer_id uuid NOT NULL);
CREATE TABLE IF NOT EXISTS public.contractor_signups (bio text, business_name text NOT NULL, city text NOT NULL, contact_name text NOT NULL, country text, created_at timestamptz NOT NULL DEFAULT now(), email text NOT NULL, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone text, photos text[] NOT NULL DEFAULT '{}', source text, specializations text[] NOT NULL DEFAULT '{}', state text, status text NOT NULL DEFAULT 'active', team_size text, website text, years_experience integer);
CREATE TABLE IF NOT EXISTS public.contractors (badge_active boolean, bio text, city text, company_name text NOT NULL, contact_email text, contact_name text, country text, created_at timestamptz, gst_number text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), jobs_completed integer, listing_type text, phone text, portfolio_photos text[], rating numeric, razorpay_subscription_id text, reviews_count integer, service_cities text[] NOT NULL DEFAULT '{}', service_states text[], source text, source_signup_id text, source_table text, specializations text[] NOT NULL DEFAULT '{}', state text, supply_categories text[] NOT NULL DEFAULT '{}', team_size integer, team_size_label text, user_id uuid, verified boolean, website text, years_experience integer);
CREATE TABLE IF NOT EXISTS public.conversation_invites (accepted_at timestamptz, conversation_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), email text NOT NULL, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invited_by uuid NOT NULL);
CREATE TABLE IF NOT EXISTS public.conversation_members (conversation_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), id uuid PRIMARY KEY DEFAULT gen_random_uuid(), last_read_at timestamptz NOT NULL DEFAULT now(), profile_id uuid NOT NULL);
CREATE TABLE IF NOT EXISTS public.conversations (created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), last_message_at timestamptz NOT NULL DEFAULT now(), org_id uuid, project_id uuid, title text, type text);
CREATE TABLE IF NOT EXISTS public.deliveries (created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item text NOT NULL, notes text, org_id uuid NOT NULL, project_id uuid NOT NULL, quantity text, scheduled_date date, status text NOT NULL DEFAULT 'active', vendor_email text, vendor_name text, vendor_profile_id uuid);
CREATE TABLE IF NOT EXISTS public.document_annotations (created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, document_id uuid, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), note text NOT NULL, org_id uuid NOT NULL, project_id uuid NOT NULL);
CREATE TABLE IF NOT EXISTS public.document_versions (created_at timestamptz NOT NULL DEFAULT now(), document_id uuid NOT NULL, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), note text, original_filename text, project_id uuid NOT NULL, r2_key text, storage_path text, uploaded_by uuid, version integer NOT NULL);
CREATE TABLE IF NOT EXISTS public.documents (approval_note text, approval_status text, approved_by uuid, created_at timestamptz NOT NULL DEFAULT now(), extension text, file_size integer, file_type text, folder text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), is_template boolean, name text, org_id uuid NOT NULL, original_filename text NOT NULL, phase text, project_id uuid, r2_key text, shared_with_client boolean NOT NULL DEFAULT false, size_bytes integer, status text NOT NULL DEFAULT 'active', storage_path text NOT NULL, uploaded_by uuid, version integer);
CREATE TABLE IF NOT EXISTS public.invoices (amount numeric NOT NULL DEFAULT 0, cgst_amount numeric, client_id uuid, client_name text NOT NULL, client_name_display text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, currency text, due_date date, gst_rate numeric, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), igst_amount numeric, invoice_number text NOT NULL, is_interstate boolean, issue_date date, line_items jsonb, milestone_label text, notes text, org_id uuid NOT NULL, paid_at timestamptz, phase text, project_id uuid, project_name text, sgst_amount numeric, status text NOT NULL DEFAULT 'active', subtotal numeric, total numeric);
CREATE TABLE IF NOT EXISTS public.issues (assigned_to uuid, created_at timestamptz, date_reported text, description text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), is_template boolean, issue_number integer NOT NULL DEFAULT 0, org_id uuid NOT NULL, photo_attached text, project_id uuid NOT NULL, reported_by text, severity text, status text NOT NULL DEFAULT 'active', title text NOT NULL, updated_at timestamptz);
CREATE TABLE IF NOT EXISTS public.material_logs (contractor text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, delivered_material text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), material_name text NOT NULL, notes text, org_id uuid NOT NULL, project_id uuid NOT NULL, specified_standard text, status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS public.meetings (action_items jsonb, agenda text, attendees text[], created_at timestamptz, created_by uuid, decisions text[], id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_date date, org_id uuid NOT NULL, project_id uuid NOT NULL, title text NOT NULL, updated_at timestamptz, starts_at timestamptz, ends_at timestamptz, location text, meeting_url text, reminder_minutes integer NOT NULL DEFAULT 0, reminder_sent_at timestamptz, invite_sent_at timestamptz, status text NOT NULL DEFAULT 'active', attendee_emails text[] NOT NULL DEFAULT '{}', notes text);
CREATE TABLE IF NOT EXISTS public.messages (attachment_name text, attachment_url text, body text NOT NULL, conversation_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid);
