CREATE TABLE IF NOT EXISTS public.organisations (address text, city text, created_at timestamptz NOT NULL DEFAULT now(), gst_number text, gst_state_code text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), logo_url text, name text NOT NULL, owner_id uuid, phone text, plan text NOT NULL DEFAULT 'free', seats_max integer, state text, type text);
