CREATE TABLE IF NOT EXISTS public.portal_questions (answer text, answered_at timestamptz, asker_email text, asker_name text, created_at timestamptz NOT NULL DEFAULT now(), id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, project_id uuid NOT NULL, question text NOT NULL, status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS public.profiles (ai_add_on boolean NOT NULL DEFAULT false, auth_id uuid NOT NULL, avatar_url text, created_at timestamptz NOT NULL DEFAULT now(), discipline text, email text, full_name text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), notification_preferences jsonb NOT NULL DEFAULT '{"email_project":true,"email_rfi":true,"email_invoice":true,"email_marketing":false}'::jsonb, notify_approvals boolean, notify_bids boolean, notify_email boolean, notify_rfi boolean, notify_meetings boolean, onboarded_at timestamptz, org_id uuid, phone text, plan text NOT NULL DEFAULT 'free', role text NOT NULL DEFAULT 'architect', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.project_expenses (amount numeric NOT NULL DEFAULT 0, category text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, description text NOT NULL, expense_date date, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, project_id uuid NOT NULL);
CREATE TABLE IF NOT EXISTS public.project_meetings (attendees text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), location text, meeting_at timestamptz NOT NULL, notes text, org_id uuid NOT NULL, project_id uuid NOT NULL, status text NOT NULL DEFAULT 'active', title text NOT NULL);
