CREATE TABLE IF NOT EXISTS public.project_teams (created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, project_id uuid NOT NULL, template_key text);
