CREATE TABLE IF NOT EXISTS public.projects (address text, architect_fee numeric, architect_fee_pct numeric, brief text, budget numeric, city text, client_id uuid, client_name text, construction_cost numeric, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, description text, end_date date, estimated_end text, floors integer, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), is_rera_registered boolean, is_template boolean, name text NOT NULL, org_id uuid NOT NULL, phase integer NOT NULL DEFAULT 0, phase_key text, portal_enabled boolean NOT NULL DEFAULT false, portal_token text, rera_number text, spec_level text, start_date date, state text, status text NOT NULL DEFAULT 'active', total_sqft numeric, type text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.punch_items (assigned_to uuid, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, defect text NOT NULL, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_number integer NOT NULL DEFAULT 0, location text, org_id uuid NOT NULL, photo_url text, project_id uuid NOT NULL, status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS public.rfis (ai_draft_response text, assigned_to uuid, attachment_url text, created_at timestamptz, description text, drawing_ref text, due_date date, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), is_scope_change boolean, is_template boolean, org_id uuid NOT NULL, project_id uuid NOT NULL, raised_by text, responded_at timestamptz, responded_by uuid, response text, rfi_number integer NOT NULL DEFAULT 0, scope_change_amount numeric, status text NOT NULL DEFAULT 'active', title text NOT NULL, updated_at timestamptz);
