CREATE TABLE IF NOT EXISTS public.rfqs (category text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, description text, due_at timestamptz, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, project_id uuid NOT NULL, quantity text, status text NOT NULL DEFAULT 'active', title text NOT NULL);
CREATE TABLE IF NOT EXISTS public.site_logs (created_at timestamptz, created_by uuid, gps_coordinates text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), observations text, org_id uuid NOT NULL, photos text[], project_id uuid NOT NULL, supervisor text, visit_date date, visit_number integer NOT NULL);
CREATE TABLE IF NOT EXISTS public.site_visits (attendees text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, gps_coordinates text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), notes text, org_id uuid NOT NULL, photo_urls text[] NOT NULL DEFAULT '{}', project_id uuid NOT NULL, supervisor text, visit_date date, visit_number integer, weather text);
CREATE TABLE IF NOT EXISTS public.submittals (contractor text, created_at timestamptz, description text, due_date date, file_name text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), is_template boolean, org_id uuid NOT NULL, project_id uuid NOT NULL, review_note text, reviewed_at timestamptz, reviewed_by uuid, revision integer, spec_section text, status text NOT NULL DEFAULT 'active', submittal_number integer NOT NULL DEFAULT 0, submitted_by uuid, title text NOT NULL, updated_at timestamptz);
CREATE TABLE IF NOT EXISTS public.tenders (awarded_bid_id text, budget_max numeric, budget_min numeric, city text, created_at timestamptz, deadline text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, project_id uuid NOT NULL, project_name text, scope text, services text[], status text, timeline_weeks integer, title text NOT NULL, trade_type text, visibility text);
CREATE TABLE IF NOT EXISTS public.transmittals (created_at timestamptz, created_by uuid, documents text, attachment_url text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL, project_id uuid NOT NULL, purpose text, recipient_company text, recipient_name text NOT NULL, sent_date date, status text NOT NULL DEFAULT 'active', transmittal_no text NOT NULL, via text);
CREATE TABLE IF NOT EXISTS public.user_integrations (access_token text NOT NULL, connected_at timestamptz, expires_at timestamptz, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), metadata jsonb, provider text NOT NULL, provider_email text, provider_name text, refresh_token text, scope text, user_id uuid NOT NULL);
CREATE TABLE IF NOT EXISTS public.vendor_catalog_imports (created_at timestamptz NOT NULL DEFAULT now(), error_message text, file_name text, file_url text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), method text NOT NULL, org_id uuid, owner_email text NOT NULL, processed_rows integer NOT NULL DEFAULT 0, sample jsonb NOT NULL DEFAULT '{}'::jsonb, source_url text, status text NOT NULL DEFAULT 'active', total_rows numeric NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), vendor_signup_id uuid);
CREATE TABLE IF NOT EXISTS public.vendor_catalog_items (brand text, category text, created_at timestamptz NOT NULL DEFAULT now(), currency text, description text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), import_id uuid, is_active boolean NOT NULL DEFAULT false, name text NOT NULL, org_id uuid, owner_email text NOT NULL, price numeric, sku text NOT NULL, unit text);
