CREATE TABLE IF NOT EXISTS public.vendor_signups (bio text, business_name text NOT NULL, catalog_file_url text, catalog_item_count integer, catalog_method text, catalog_notes text, categories text[] NOT NULL DEFAULT '{}', city text NOT NULL, contact_name text NOT NULL, country text, created_at timestamptz NOT NULL DEFAULT now(), email text NOT NULL, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone text, photos text[] NOT NULL DEFAULT '{}', source text, state text, status text NOT NULL DEFAULT 'active', team_size text, website text, years_experience integer);
CREATE TABLE IF NOT EXISTS public.waitlist (city text, country text, created_at timestamptz NOT NULL DEFAULT now(), email text NOT NULL, firm text, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text, role text);
CREATE TABLE IF NOT EXISTS public.whatsapp_messages (direction text, filename text, from_number text NOT NULL, id uuid PRIMARY KEY DEFAULT gen_random_uuid(), media_id text, message_id text NOT NULL, received_at timestamptz, status text, text text, to_number text, type text);

DO $$
DECLARE t text;
BEGIN
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'public'
  LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t);
    EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
  END LOOP;
END $$;